import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, uniform, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Mesh, PlaneGeometry, Group } = ctx.THREE;

  // Root group
  const group = new Group();
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Plane geometry (7 units wide, 6 units tall)
  const geometry = new PlaneGeometry(7, 6);

  // Material with gradient + text overlay
  const colorInk = new vec3(0.086, 0.086, 0.114); // #16161d
  const colorPaper = new vec3(0.91, 0.925, 0.949); // #e8ecf2
  const colorAccent = new vec3(1.0, 0.165, 0.22); // #ff2a38
  const colorSurface = new vec3(0.043, 0.043, 0.063); // #0b0b10

  // Vertical gradient from surface to ink with subtle accent
  const gradientNode = mix(colorSurface, colorInk, uv().y);

  // Material
  const material = new MeshBasicNodeMaterial();
  material.colorNode = gradientNode;

  // Create mesh
  const plane = new Mesh(geometry, material);
  group.add(plane);

  // Add text content from config
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  if (textItems.length > 0) {
    const item = textItems[0];
    const textContent = item.text || '';
    const fontSize = item.typography?.fontSize ?? 31;

    // Create text using fontAtlas
    const textMesh = ctx.fontAtlas.createText(textContent, {
      fontSize,
      color: '#e8ecf2', // paper color for contrast
      align: 'center',
      maxWidthPx: 600,
      letterSpacingPx: 0
    });

    // Position text centered on plane
    textMesh.position.set(0, 0, 0.1);
    group.add(textMesh);
  }

  // Cleanup handler
  group.userData.cleanup = function() {
    geometry.dispose();
    material.dispose();
  };

  // Empty handlers object (no interactivity)
  group.userData.handlers = {};

  return group;
}
